mapper.sql:
SELECT '账平' AS category, -- 类别 t.bill_date AS bill_date, -- 结算日期 t.insutype AS insur_type, -- 类型代码 DECODE(t.insutype, '310', '职工', '390', '居民', '3101', '异地职工', '3901', '异地居民', '515253', '生育') AS insur_type_name, -- 类型名称 COUNT(t.setl_id) AS qty, -- 条数 SUM(t.medfee_sumamt) AS medfee_sumamt, -- 医疗费总额 SUM(t.acct_pay) AS acct_pay, -- 个人账户支出 SUM(t.hlfp_pay) AS hlfp_pay, -- 统筹基金支出 SUM(t.cash_pay) AS cash_pay, -- 现金支出 SUM(t.cvlserv_pay) AS cvlserv_pay, -- 公务员补助支出 SUM(t.hlfes_pay) AS hlfes_pay, -- 企业补充医保支出 SUM(t.hlfmi_pay) AS hlfmi_pay, -- 居民大病支出 SUM(t.hlfob_pay) AS hlfob_pay, -- 职工大病支出 SUM(t.maf_pay) AS maf_pay, -- 医疗救助支出 SUM(t.oth_pay) AS oth_pay -- 其他支出 FROM ips_dz_biz_bills t WHERE t.zp_flag = 1 AND t.bill_date BETWEEN TO_DATE(#{startDate}, 'yyyy-mm-dd') AND TO_DATE(#{endDate}, 'yyyy-mm-dd')
AND t.insutype = #{insurType}
GROUP BY t.insutype, t.bill_date UNION ALL SELECT '医保负金额-退费' AS category, -- 类别 b.bill_date AS bill_date, -- 结算日期 b.insutype AS insur_type, -- 类型代码 DECODE(b.insutype, '310', '职工', '390', '居民', '3101', '异地职工', '3901', '异地居民', '515253', '生育') AS insur_type_name, -- 类型名称 COUNT(b.setl_id) AS qty, -- 条数 SUM(b.medfee_sumamt) AS medfee_sumamt, -- 医疗费总额 SUM(b.acct_pay) AS acct_pay, -- 个人账户支出 SUM(b.hlfp_pay) AS hlfp_pay, -- 统筹基金支出 SUM(b.cash_pay) AS cash_pay, -- 现金支出 SUM(b.cvlserv_pay) AS cvlserv_pay, -- 公务员补助支出 SUM(b.hlfes_pay) AS hlfes_pay, -- 企业补充医保支出 SUM(b.hlfmi_pay) AS hlfmi_pay, -- 居民大病支出 SUM(b.hlfob_pay) AS hlfob_pay, -- 职工大病支出 SUM(b.maf_pay) AS maf_pay, -- 医疗救助支出 SUM(b.oth_pay) AS oth_pay -- 其他支出 FROM ips_dz_pay_bills b INNER JOIN ips_dz_biz_bills a ON a.INSUTYPE = b.INSUTYPE AND a.TRAN_TYPE = 1 AND a.mdtrt_id = b.mdtrt_id AND a.medfee_sumamt = -b.medfee_sumamt AND a.bill_date <= b.bill_date AND a.bill_date BETWEEN TO_DATE(#{prevStart}, 'yyyy-mm-dd') AND TO_DATE(#{endDate}, 'yyyy-mm-dd') WHERE b.TRAN_TYPE = 2 AND b.zp_flag = -1 AND b.bill_date BETWEEN TO_DATE(#{startDate}, 'yyyy-mm-dd') AND TO_DATE(#{endDate}, 'yyyy-mm-dd')
AND b.insutype = #{insurType}
GROUP BY b.insutype, b.bill_date UNION ALL SELECT '医保正金额-收费' AS category, -- 类别 a.bill_date AS bill_date, -- 结算日期 a.insutype AS insur_type, -- 类型代码 DECODE(a.insutype, '310', '职工', '390', '居民', '3101', '异地职工', '3901', '异地居民', '515253', '生育') AS insur_type_name, -- 类型名称 COUNT(a.setl_id) AS qty, -- 条数 SUM(a.medfee_sumamt) AS medfee_sumamt, -- 医疗费总额 SUM(a.acct_pay) AS acct_pay, -- 个人账户支出 SUM(a.hlfp_pay) AS hlfp_pay, -- 统筹基金支出 SUM(a.cash_pay) AS cash_pay, -- 现金支出 SUM(a.cvlserv_pay) AS cvlserv_pay, -- 公务员补助支出 SUM(a.hlfes_pay) AS hlfes_pay, -- 企业补充医保支出 SUM(a.hlfmi_pay) AS hlfmi_pay, -- 居民大病支出 SUM(a.hlfob_pay) AS hlfob_pay, -- 职工大病支出 SUM(a.maf_pay) AS maf_pay, -- 医疗救助支出 SUM(a.oth_pay) AS oth_pay -- 其他支出 FROM ips_dz_pay_bills a WHERE a.TRAN_TYPE = 1 AND a.zp_flag = -1 AND a.bill_date BETWEEN TO_DATE(#{startDate}, 'yyyy-mm-dd') AND TO_DATE(#{endDate}, 'yyyy-mm-dd')
AND a.insutype = #{insurType}
GROUP BY a.insutype, a.bill_date

mapper.select:
SELECT b.insutype AS insur_type, -- 类型代码 DECODE(b.insutype, '310', '职工', '390', '居民', '3101', '异地职工', '3901', '异地居民', '515253', '生育') AS insur_type_name, -- 类型名称 COUNT(b.setl_id) AS refund_total, -- 当月退费总条数 SUM(CASE WHEN a.setl_id IS NOT NULL AND TO_CHAR(a.bill_date, 'yyyy-mm') != TO_CHAR(b.bill_date, 'yyyy-mm') THEN 1 ELSE 0 END) AS cross_cnt, -- 跨月匹配条数 SUM(CASE WHEN a.setl_id IS NULL THEN 1 ELSE 0 END) AS none_cnt -- 找不到条数 FROM ips_dz_pay_bills b LEFT JOIN ips_dz_biz_bills a ON a.INSUTYPE = b.INSUTYPE AND a.TRAN_TYPE = 1 AND a.mdtrt_id = b.mdtrt_id AND a.medfee_sumamt = -b.medfee_sumamt AND a.bill_date <= b.bill_date AND a.bill_date BETWEEN TO_DATE(#{prevStart}, 'yyyy-mm-dd') AND TO_DATE(#{endDate}, 'yyyy-mm-dd') WHERE b.TRAN_TYPE = 2 AND b.zp_flag = -1 AND b.bill_date BETWEEN TO_DATE(#{startDate}, 'yyyy-mm-dd') AND TO_DATE(#{endDate}, 'yyyy-mm-dd')
AND b.insutype = #{insurType}
GROUP BY b.insutype, d.insutype_name ORDER BY b.insutype
